#!/usr/bin/env bash
# Build both Samsung .wgt packages: the core launcher + the Home-key wrapper.
# Inlines the shared catalogs (../../catalogs/) into the launcher bundle.
set -euo pipefail
cd "$(dirname "$0")"

python3 - <<'PY'
import json, os
apps = json.load(open('../../catalogs/apps.json'))
extra_path = '../../catalogs/apps-extra.json'
extra = json.load(open(extra_path)) if os.path.exists(extra_path) else []
open('../../core/launcher/js/catalog.js', 'w').write(
    '/* generated by build.sh from catalogs/apps.json and catalogs/apps-extra.json */\n'
    'var CATALOG = %s;\n'
    'var CATALOG_EXTRA = %s;\n'
    % (json.dumps(apps, ensure_ascii=False, indent=2),
       json.dumps(extra, ensure_ascii=False, indent=2)))
PY

CORE=../../core/launcher
rm -f freshhome-launcher.wgt
( cd "$CORE" && zip -X -q "$OLDPWD/freshhome-launcher.wgt" \
    config.xml index.html css/style.css js/app.js js/catalog.js js/device.js \
    js/input.js games/snake.html games/breakout.html games/g2048.html )

rm -f freshhome-homekey.wgt
( cd homekey && zip -X -q "$OLDPWD/freshhome-homekey.wgt" config.xml index.html )

echo "built: freshhome-launcher.wgt, freshhome-homekey.wgt (in platforms/samsung-tizen/)"
